{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "AZD0837, a close structural analogue in the same oral thrombin-inhibitor prodrug class with a benzamidine-like group and ester/amide prodrug motifs, has absolute oral bioavailability of 22–52% in humans, directly supporting F≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Inogatran, a related peptidic thrombin inhibitor without the ester/hydroxyamidine prodrug masking, has <5% oral bioavailability in healthy volunteers; this low value is not transferable to the query because the query's prodrug groups are designed to overcome such permeability limitations.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Perindopril, an ethyl ester prodrug ACE inhibitor, has mean absolute oral bioavailability of 66–95% in humans, supporting that ester prodrugs of polar peptide-like acids can achieve high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Quinapril, another ethyl ester prodrug ACE inhibitor, has absolute oral bioavailability of about 50% in humans, supporting high F for the query's ester prodrug design.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Moexipril, an ester prodrug ACE inhibitor, has oral bioavailability of 22% in humans, just meeting the F≥20% threshold and supporting a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Oseltamivir, an ethyl ester prodrug, has absolute oral bioavailability of 79% in healthy volunteers, supporting that ester prodrug masking can yield high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue AZD0837, in the same oral thrombin-inhibitor prodrug class, has absolute F of 22–52%, and multiple ester prodrugs (perindopril, quinapril, moexipril, oseltamivir) show F ≥22%, supporting high. The only low-F analogue, inogatran, lacks the prodrug masking present in the query and therefore carries little weight. Overall, F≥20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query itself.",
    "The exact value may be near the 20% threshold, so small differences in formulation or study conditions could affect classification.",
    "Distinction between bioavailability of the prodrug versus the active metabolite is not fully resolved for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

